import hero from '../../public/hero/manifest.json';

// The hero manifest is generated by scripts/build-assets.mjs, which counts the frames it finds.
export const HERO_FRAMES = { base: '/hero', ...hero };

export const frameUrl = (m, i) => `${m.base}/${m.pattern.replace('{n}', String(i + 1).padStart(m.pad ?? 3, '0'))}`;
